helpers=''' async function decryptValue(key:CryptoKey,ciphertext:string|null,iv:string|null){if(!ciphertext||!iv)return null;const plain=await crypto.subtle.decrypt({name:"AES-GCM",iv:b64ToBytes(iv)},key,b64ToBytes(ciphertext));return new TextDecoder().decode(plain);}\n async function portalCredential(clientId:string){const {data,error}=await ops.from("client_access_vault").select("login_ciphertext,login_iv,password_ciphertext,password_iv").eq("client_id",clientId).eq("category","PORTAL").eq("system_name","Briefing Hub").order("created_at",{ascending:false}).limit(1).maybeSingle();if(error||!data)return null;const key=await vaultKey();const [login,password]=await Promise.all([decryptValue(key,data.login_ciphertext,data.login_iv),decryptValue(key,data.password_ciphertext,data.password_iv)]);return login&&password?{login,password}:null;}\n function driveIdFromUrl(v:string){const s=String(v||"");for(const re of [/\\/folders\\/([A-Za-z0-9_-]{10,})/i,/[?&]id=([A-Za-z0-9_-]{10,})/i,/^([A-Za-z0-9_-]{20,})$/]){const m=s.match(re);if(m?.[1])return m[1];}return null;}\n async function resolveDriveViaBriefing(client:any){try{const cred=await portalCredential(client.id);if(!cred)return null;const base="https://agency-briefing-hub.lakassessoriadigital.workers.dev";const lr=await fetch(base+"/api/client/login",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({username:cred.login,password:cred.password}),signal:AbortSignal.timeout(20000)});if(!lr.ok)return null;const cookie=(lr.headers.get("set-cookie")||"").split(";")[0];if(!cookie)return null;const mr=await fetch(base+"/api/client/materials",{headers:{cookie},signal:AbortSignal.timeout(25000)});const x=await mr.json().catch(()=>({}));if(!mr.ok||x?.ready!==true)return null;const folderId=driveIdFromUrl(String(x.folder_url||""));return folderId?{folder_id:folderId,folder_name:String(x.folder_name||client.display_name),source:"BRIEFING_DRIVE_BRIDGE"}:null;}catch{return null;}}\n async function persistDrive(client:any,folderId:string,folderName:string,matchedBy:string){const {error}=await ops.from("client_integrations").upsert({client_id:client.id,system:"DRIVE",external_id:folderId,external_name:folderName||client.display_name,confidence:"ALTA",matched_by:matchedBy,is_primary:true,metadata:{provisioned_at:new Date().toISOString(),provisioned_by:"agency-ops-client-provisioner"}},{onConflict:"system,external_id"});if(error)throw new Error(`drive_link:${errText(error)}`);return {ready:true,folder_id:folderId,folder_name:folderName||client.display_name};}\n'''
if anchor not in s: raise SystemExit('anchor missing')
